import { Tag } from "@chakra-ui/react";
import type { IconDefinition } from "@fortawesome/fontawesome-svg-core";
import { Brain, DiagramProject, Dumbbell, Icon, Wrench } from "../../Icon";
import { Tooltip } from "../../Tooltip";
import type { Reference, ReferenceKind } from "./references";

const KIND_CONFIG: Record<ReferenceKind, { palette: string; label: string; icon: IconDefinition }> =
  {
    tool: { palette: "purple", label: "Tool", icon: Wrench },
    // Same glyph as the skill-activated log rows: skills are "trained".
    skill: { palette: "pink", label: "Skill", icon: Dumbbell },
    block: { palette: "cyan", label: "Ordered block", icon: DiagramProject },
    memory: { palette: "orange", label: "Memory", icon: Brain },
  };

interface BaseReferenceTagProps {
  readonly name: string;
  readonly kind: ReferenceKind;
  readonly tooltip: string;
  readonly disabled?: boolean;
}

/** Shared inline-pill chrome for every reference kind. */
function BaseReferenceTag({ name, kind, tooltip, disabled = false }: BaseReferenceTagProps) {
  const { palette, icon } = KIND_CONFIG[kind];
  return (
    <Tooltip content={tooltip}>
      <Tag.Root
        colorPalette={disabled ? "gray" : palette}
        opacity={disabled ? "deactivated" : undefined}
        data-disabled={disabled || undefined}
        variant="surface"
        size="sm"
        // Inline among prose: middle keeps the pill on the text line. The icon
        // is a plain flex child (Tag.StartElement's recipe margins and the
        // FontAwesome baseline shift push it below center).
        display="inline-flex"
        alignItems="center"
        gap="1.5"
        verticalAlign="middle"
        data-testid={`skill-reference-${kind}`}
      >
        <Icon icon={icon} size="sm" />
        <Tag.Label>{name}</Tag.Label>
      </Tag.Root>
    </Tooltip>
  );
}

function formatMemoryValue(value: unknown): string {
  if (value === undefined || value === null) return "<unknown>";
  if (typeof value === "string") return value;
  return JSON.stringify(value);
}

interface MemoryReferenceTagProps {
  readonly name: string;
  /** Current memory value, surfaced in the tooltip; `<unknown>` when unset. */
  readonly value: unknown;
}

/**
 * Inline highlight for a memory reference. Memory is never gated off and always
 * carries a value, so it does not share the gate/disabled logic of the other
 * reference kinds.
 */
export function MemoryReferenceTag({ name, value }: MemoryReferenceTagProps) {
  return (
    <BaseReferenceTag name={name} kind="memory" tooltip={`Memory: ${formatMemoryValue(value)}`} />
  );
}

interface ReferenceTagProps {
  readonly name: string;
  /** A tool / skill / ordered-block reference (memory uses MemoryReferenceTag). */
  readonly reference: Reference;
  /** Gated off in the current state: muted, with an explanatory tooltip. */
  readonly disabled?: boolean;
}

/** Inline highlight for a tool / skill / ordered-block name in skill prose. */
export function ReferenceTag({ name, reference, disabled = false }: ReferenceTagProps) {
  const { label } = KIND_CONFIG[reference.kind];
  const tooltip = disabled
    ? `${label}: ${reference.target} — currently disabled (gate condition not met), not offered to the LLM`
    : `${label}: ${reference.target}`;
  return (
    <BaseReferenceTag name={name} kind={reference.kind} tooltip={tooltip} disabled={disabled} />
  );
}
